async function ensureFilesLoaded(project, forceReload = false) {
  const { $state, $api } = project
  if (!$state || !$api) return
  if ($state.files && !forceReload) return
  const data = await promiseOrDefault(() => $api.knowledge.files(), null)
  if (data) {
